def jsonb_get(data: dict, path: str, default=None):
    """安全读取嵌套 JSON 字段。
    路径用点分隔（如 'a.b.c'）；任一层缺失或不是 dict 都返回 default。
    """
    if not path:
        return data

    current = data
    for key in path.split("."):
        if not isinstance(current, dict) or key not in current:
            return default
        current = current[key]
    return current

